import React, { useState } from 'react';
import { User, Briefcase, X, FileText, Award, ShieldCheck } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);

  // Your background image link
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsVerifying(true);
    setTimeout(() => {
      alert("Information sent for verification. You will be notified soon!");
      setShowModal(null);
      setIsVerifying(false);
    }, 2000);
  };

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center p-6 font-sans bg-cover bg-center bg-no-repeat relative"
      style={{ 
        backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url(${bgImage})` 
      }}
    >
      {/* Content Container */}
      <div className="text-center mb-10 z-10">
        <h1 className="text-5xl font-black text-white mb-3 tracking-tight">Create Your Account</h1>
        <p className="text-gray-200 text-lg font-medium">Join the most trusted Talent Pool Management System</p>
      </div>
      
      {/* The Central Oval Toggle with Glassmorphism */}
      <div className="bg-white/90 backdrop-blur-xl p-2 rounded-[3rem] shadow-2xl flex border border-white/20 w-full max-w-lg z-10 transition-all hover:shadow-purple-500/20">
        <button 
          onClick={() => setShowModal('student')}
          className="flex-1 flex flex-col items-center justify-center py-8 rounded-[2.5rem] hover:bg-purple-600 group transition-all"
        >
          <div className="bg-purple-100 text-purple-600 p-4 rounded-full mb-3 group-hover:bg-white group-hover:scale-110 transition-all shadow-md">
            <User size={32} />
          </div>
          <span className="font-bold text-gray-800 group-hover:text-white text-lg">Student</span>
        </button>

        <div className="w-[1px] bg-gray-200/50 my-6"></div>

        <button 
          onClick={() => setShowModal('hr')}
          className="flex-1 flex flex-col items-center justify-center py-8 rounded-[2.5rem] hover:bg-blue-600 group transition-all"
        >
          <div className="bg-blue-100 text-blue-600 p-4 rounded-full mb-3 group-hover:bg-white group-hover:scale-110 transition-all shadow-md">
            <Briefcase size={32} />
          </div>
          <span className="font-bold text-gray-800 group-hover:text-white text-lg">HR / Company</span>
        </button>
      </div>

      {/* Registration Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-300">
            
            {/* Header */}
            <div className={`p-8 text-white flex justify-between items-center ${showModal === 'student' ? 'bg-[#7c5dfa]' : 'bg-[#2563eb]'}`}>
              <div className="flex items-center gap-3">
                <ShieldCheck size={28} />
                <h2 className="text-2xl font-black uppercase tracking-tight">
                  {showModal === 'student' ? 'Student Verification' : 'Company Verification'}
                </h2>
              </div>
              <button 
                onClick={() => setShowModal(null)} 
                className="bg-white/20 p-2 rounded-full hover:bg-white/40 hover:rotate-90 transition-all"
              >
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-10 grid grid-cols-1 md:grid-cols-2 gap-5 max-h-[75vh] overflow-y-auto">
              {showModal === 'student' ? (
                <>
                  <div className="col-span-2 text-xs font-black text-gray-400 uppercase tracking-widest">Basic Info</div>
                  <input type="text" placeholder="Full Name" className="input-style" required />
                  <input type="text" placeholder="College Name" className="input-style" required />
                  <div className="col-span-2 text-xs font-black text-gray-400 uppercase tracking-widest mt-2">Professional Info</div>
                  <input type="text" placeholder="Key Skills (e.g. Java, React)" className="input-style" required />
                  <select className="input-style" required>
                    <option value="">Experience Level</option>
                    <option value="fresher">Fresher</option>
                    <option value="intern">Internship (6mo+)</option>
                    <option value="junior">Junior (1yr+)</option>
                  </select>
                  <div className="col-span-2 border-2 border-dashed border-purple-100 p-8 rounded-[2rem] text-center bg-purple-50/50 hover:bg-purple-50 transition-colors">
                    <FileText className="mx-auto text-purple-500 mb-3" size={32} />
                    <p className="text-sm font-bold text-gray-700">Upload Resume & Certificates</p>
                    <input type="file" className="mt-4 text-xs block w-full text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:bg-purple-600 file:text-white hover:file:bg-purple-700 cursor-pointer" required multiple />
                  </div>
                </>
              ) : (
                <>
                  <div className="col-span-2 text-xs font-black text-gray-400 uppercase tracking-widest">Company Info</div>
                  <input type="text" placeholder="Company Name" className="input-style" required />
                  <input type="text" placeholder="Company Website" className="input-style" required />
                  <input type="text" placeholder="Registration ID" className="input-style" required />
                  <input type="text" placeholder="Official HR Email" className="input-style" required />
                  <div className="col-span-2 text-xs font-black text-gray-400 uppercase tracking-widest mt-2">Hiring Needs</div>
                  <input type="text" placeholder="Job Roles (e.g. SDE-1)" className="input-style" required />
                  <input type="text" placeholder="Required Skills" className="input-style" required />
                  <div className="col-span-2 border-2 border-dashed border-blue-100 p-8 rounded-[2rem] text-center bg-blue-50/50 hover:bg-blue-50 transition-colors">
                    <Award className="mx-auto text-blue-500 mb-3" size={32} />
                    <p className="text-sm font-bold text-gray-700">Upload HR Identity / License</p>
                    <input type="file" className="mt-4 text-xs block w-full text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:bg-blue-600 file:text-white hover:file:bg-blue-700 cursor-pointer" required />
                  </div>
                </>
              )}

              <button 
                type="submit"
                disabled={isVerifying}
                className={`col-span-2 py-5 rounded-2xl font-black text-white shadow-xl transition-all transform active:scale-95 flex items-center justify-center gap-2 mt-4 text-lg tracking-wide ${
                  isVerifying ? 'bg-orange-500 animate-pulse' : (showModal === 'student' ? 'bg-[#7c5dfa] hover:bg-[#6a4dec]' : 'bg-[#2563eb] hover:bg-[#1d4ed8]')
                }`}
              >
                {isVerifying ? 'AUTHENTICATING DATA...' : 'SUBMIT FOR VERIFICATION'}
              </button>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .input-style {
          width: 100%;
          padding: 1rem 1.25rem;
          background-color: #f8fafc;
          border: 2px solid #f1f5f9;
          border-radius: 1.25rem;
          outline: none;
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
          font-weight: 500;
        }
        .input-style:focus {
          border-color: #7c5dfa;
          box-shadow: 0 0 0 5px rgba(124, 93, 250, 0.15);
          background-color: white;
          transform: translateY(-2px);
        }
      `}</style>
    </div>
  );
};

export default Register;
